from pathlib import Path
p=Path('screens.js');s=p.read_text(encoding='utf-8-sig')
s=s.replace('登録10人','登録16人').replace('s.roster.length>=10','s.roster.length>=16').replace('25%軽減','20%軽減').replace('品質 ×','品質 Q').replace('施設品質 ×','施設品質 Q').replace("method==='physical'?120:80","method==='physical'?140:90")
s=s.replace("${partyLevel()<v.unlock?'disabled':''}","${!canJob(h,id)?'disabled':''}").replace("${partyLevel()<v.unlock?' / 平均Lv.'+v.unlock+'必要':''}","${' / '+esc(jobRequirementText(v))}")
s=s.replace("${jobs.map(([id,j])=>`<option value=", "${jobs.filter(([,j])=>j.base).map(([id,j])=>`<option value=")
s=s.replace('解放はパーティー平均レベル','個人レベル・職業経験・習得技能で派生').replace('${esc(j.name)} <span class="chip">平均Lv.${j.unlock}</span>','${esc(j.name)} <span class="chip">${esc(jobRequirementText(j))}</span>')
s=s.replace("amount=q?(s.materials[q.material]||0):0","quality=map.quality||Math.min(13,1+Math.floor(map.level/25)),amount=q?availableMaterial(q.material,quality):0")
s=s.replace('${q.amount}個を納品','Q${quality}以上 ${q.amount}個を納品')
s=s.replace("(s.materials[id]||0)<n)?'disabled':'','primary wide'","availableMaterial(id,quote.quality)<n)?'disabled':'','primary wide'")
s=s.replace("(s.materials[id]||0)<n)?'disabled':''}`)","availableMaterial(id,quote.nextQuality)<n)?'disabled':''}`)")
s=s.replace('<h2>装備を製作</h2>','<h2>装備を製作</h2><label class="field">品質<select data-change="craftQuality">${Array.from({length:currentTown().quality},(_,i)=>i+1).map(q=>`<option value="${q}" ${q===quote.quality?\'selected\':\'\'}>Q${q} / 性能 ×${qualityFactor(q).toFixed(2)}</option>`).join(\'\')}</select></label>')
s=s.replace("'購入 '+b.cost+' G'","'購入 '+Math.ceil(b.cost*currentTown().price)+' G'").replace('s.gold<b.cost','s.gold<Math.ceil(b.cost*currentTown().price)')
s=s.replace("h.lv<sk.level||h.mp<sk.mp?'disabled'","h.lv<sk.level||h.mp<sk.mp||h.sp<(sk.sp||0)?'disabled'")
s=s.replace('MP ${sk.mp}${h.lv<sk.level','MANA ${sk.mp} / SP ${sk.sp||0}${h.lv<sk.level')
s=s.replace('全員のHP・MPを全回復','全員のLIFE・MANA・SPを全回復')
s=s.replace('${owner?esc(owner.name)+\'が装備中\':\'未装備\'}','${esc(gearRequirementText(g))}<br>${owner?esc(owner.name)+\'が装備中\':\'未装備\'}')
p.write_text(s,encoding='utf-8')
